 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Separator rows/columns contain a dense run of their line color and sparse
    # marker cells; select lines with at least two cells unlike global background.
    rows = [r for r, row in enumerate(grid) if sum(v != bg for v in row) >= 2]
    cols = [c for c in range(w) if sum(grid[r][c] != bg for r in range(h)) >= 2]
    out = []
    for ra, rb in zip(rows, rows[1:]):
        result_row = []
        for ca, cb in zip(cols, cols[1:]):
            corners = [grid[ra][ca], grid[ra][cb], grid[rb][ca], grid[rb][cb]]
            if corners.count(corners[0]) == 4:
                result_row.append(corners[0])
            else:
                result_row.append(grid[(ra + rb) // 2][(ca + cb) // 2])
        out.append(result_row)
    return out
